// === Tab: audio ===
// A submission for @sableRaph's weekly creative challenge on Twitch (#WCCChallenge)
// https://www.twitch.tv/sableraph
// "peace"

const config = {
	vol: 0,
	bpm: 36,
	high: {
		"volume": -8,
		"oscillator": {
			"type": "triangle2",
		},
		"envelope": {
			// "attack": 2.0,
			"decay": 0.0,
			"sustain": 1.0,
			// "release": 3.5,
			"attackCurve": "cosine",
			"releaseCurve": "linear"
		},
	},
	bass: {
		"volume": -4,
		"oscillator": {
			"type": "fatsawtooth4",
			"count": 4,
			"spread": 30
		},
		"envelope": {
			// "attack": 2.0,
			"decay": 0.0,
			"sustain": 1.0,
			// "release": 3.5,
			"attackCurve": "linear",
			"releaseCurve": "linear"
		},
	},
	freeverb: {
		"roomSize": 0.875,
		"dampening": 800,
		"wet": 0.375
	},
	highpass: {
		"frequency": 440,
		"type": "highpass",
		"rolloff": -12,
	},
	pattern: [1, null, 2, null, null, 3, null, 4, null, null],
	state: [true, null, false, null, null],
	pitch: {
		highOne: ["D3", "E3", "D3", "E3"],
		highTwo: ["A3", "G#3", "A3", "G#3"],
		bass: ["F1", "E1", "D1", "E1"],
	},
	duration: {
		high: ["8n", "8n.", "8n", "8n."],
		bass: ["4n", "4n.", "4n", "4n."],
	},
	notes: {}
}

function serializeNotes(pitch, duration) {
	return config.pattern.map((i) => {
		return (i) ? {pitch: pitch[i - 1], duration: duration[i - 1]} : i;
	})
}

function initAudio() {
	Tone.Destination.volume.value = -Infinity;
	Tone.Destination.output.set({'gain': 0.75});
	Tone.Transport.timeSignature = [5, 4];
	Tone.Transport.bpm.value = config.bpm;

	const quarterNoteTime = Tone.Time("4n").toSeconds();
	config.high.envelope.attack = 0.6 * quarterNoteTime;
	config.high.envelope.release = 1.8 * quarterNoteTime;
	config.bass.envelope.attack = 0.9 * quarterNoteTime;
	config.bass.envelope.release = 1.8 * quarterNoteTime;

	config.notes.highOne = serializeNotes(config.pitch.highOne, config.duration.high);
	config.notes.highTwo = serializeNotes(config.pitch.highTwo, config.duration.high);
	config.notes.bass = serializeNotes(config.pitch.bass, config.duration.bass);
}

function initSynths() {
	synths.highOne = new Tone.Synth(config.high);
	synths.highTwo = new Tone.Synth(config.high);
	synths.bass = new Tone.Synth(config.bass);
}

function initEffects() {
	effects.highpass = new Tone.Filter(config.highpass);
	effects.freeverb = new Tone.Freeverb(config.freeverb);

	effects.freeverb.output.set({'gain': 0.5});
}

function initSequences() {
	const stateCallback = (time, state) => {
		sequenceState = state;

		if (!debugAudio) return;
		const bbs = Tone.TransportTime().toBarsBeatsSixteenths();
		console.log(bbs, nfc(time, 2));
	};
	/*
	const audioCallback = (time, notes) => {
		for (const [synth, value] of Object.entries(notes)) {
			console.log(synth);
			synths[synth].triggerAttackRelease(notes[key].pitch, notes[key].duration, time);
		}		
	};
	*/
	const highOneCallback = (time, { pitch, duration }) => {
		synths.highOne.triggerAttackRelease(pitch, duration, time);
	};
	const highTwoCallback = (time, { pitch, duration }) => {
		synths.highTwo.triggerAttackRelease(pitch, duration, time);
	};
	const bassCallback = (time, { pitch, duration }) => {
		synths.bass.triggerAttackRelease(pitch, duration, time);
	};
	const interval = '4n';

	sequences.state = new Tone.Sequence(stateCallback, config.state, interval).start(0); 
	//sequences.audio = new Tone.Sequence(highOneCallback, config.notes, interval).start(0);

	sequences.highOne = new Tone.Sequence(highOneCallback, config.notes.highOne, interval).start(0);
	sequences.highTwo = new Tone.Sequence(highTwoCallback, config.notes.highTwo, interval).start(0);
	sequences.bass = new Tone.Sequence(bassCallback, config.notes.bass, interval).start(0);}

function connectAudioNodes() {
	synths.highOne.connect(effects.highpass);
	synths.highTwo.connect(effects.highpass);
	effects.highpass.toDestination();

	synths.bass.toDestination()
}

function connectAudioNodesWithFreeverb() {
	synths.highOne.connect(effects.freeverb);
	synths.highTwo.connect(effects.freeverb);
	effects.freeverb.connect(effects.highpass);
	effects.highpass.toDestination();

	synths.bass.toDestination();
}

// === Tab: shader ===
const vert = `
precision highp float;
precision highp int;

attribute vec3 aPosition;

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  gl_Position = positionVec4;
}
`;

const frag = `
#ifdef GL_ES
precision highp float;
#endif

uniform vec2 uResolution;
uniform float uRadius;
// uniform float uOpacity;
// uniform float uColor;
uniform float uHigh;
uniform float uBass;

void main() {
	vec2 uv = (gl_FragCoord.xy - 0.5 * uResolution.xy) / uResolution.y;

	float d = length(uv);

	float minRadius = 0.025;
	float maxRadius = 0.275;

	float mHigh = min(1., (minRadius + uRadius * maxRadius) / d);
	float mBass = 1. - uBass * smoothstep(mHigh, mHigh + 1., d);

	float b = uBass * mBass;
	float h = uHigh * mHigh;

	vec3 rgb = h * vec3(.25, .625, 0.) + b * vec3(.75, .125, 0.);
	// vec3 rgb = mix(h * vec3(.9, .8, 0.), b * vec3(.8, .3, 0.), .5);

	gl_FragColor = vec4(rgb, 1);
}
`;

// === Tab: sketch ===
document.body.style.backgroundColor = 'hsl(0, 0%, 8%)';

////////////////////////////////////////////////////////

const synths = {};
const effects = {};
const sequences = {};

let sequenceState = false;
let debugAudio = false;

initAudio();
initSynths();
initEffects();
initSequences();

// To avoid clipping and cracking 

// uncomment this
// connectAudioNodes();

// comment this
connectAudioNodesWithFreeverb();

////////////////////////////////////////////////////////

const getMaximumSize = () => Math.max(windowWidth, windowHeight);

// center of canvas
let o;
// output
let p;
// shader
let s;

function setup() {
	const cnvSize = 0.9 * getMaximumSize();
	createCanvas(cnvSize, cnvSize);
	pixelDensity(1);

	o = createVector(0.5 * cnvSize, 0.5 * cnvSize);

	p = createGraphics(cnvSize, cnvSize, WEBGL);
	p.colorMode(RGB, 1, 1, 1, 1);
	p.pixelDensity(1);
	p.noStroke();

	s = p.createShader(vert, frag);
}

function windowResized() {
	var cnvSize = 0.9 * getMaximumSize();
	o.set(0.5 * cnvSize, 0.5 * cnvSize);
	p.resizeCanvas(cnvSize, cnvSize);
}

////////////////////////////////////////////////////////

const exponentialIn = (n) => (n == 0.0) ? n : Math.pow(2, 10 * (n - 1))
const exponentialOut = (n) => (n == 1.0) ? n : 1 - Math.pow(2, -10 * n);

let initialised = false; // on user input

let normedRadius = 1;
let normedIncrement = 0;
let lerpedRadius = 1;

let highValue = 0;
let bassValue = 0;

function draw() {	
	if (Tone.Transport.state === 'started') {
		normedIncrement = (sequenceState) ? -0.00625 : 0.00375;
		normedRadius = constrain(normedRadius + normedIncrement, 0, 1);
		lerpedRadius = (sequenceState) ? exponentialIn(normedRadius) : exponentialOut(normedRadius);
		highValue = synths.highOne.envelope.value;
		bassValue = synths.bass.envelope.value;
	}
	else {
		normedRadius = 1;
		lerpedRadius = 1;
		highValue = 0;
		bassValue = 0;
	}

	clear();
	p.noStroke();
	p.shader(s);
	s.setUniform('uResolution', [p.width, p.height]);
	s.setUniform('uRadius', lerpedRadius);
	s.setUniform('uHigh', highValue);
	s.setUniform('uBass', bassValue);
	p.rect(-o.x, -o.y, p.width, p.height);
	image(p, 0, 0);

	if (!initialised) {
		push();
		fill(255);
		textAlign(CENTER, CENTER);
		text('Press [Spacebar] to play', o.x, o.y);
		pop();
	}
}

////////////////////////////////////////////////////////

async function keyReleased() {
	if (keyCode !== 32) return;

	if (!initialised) {
		initialised = true;
		await Tone.start();

		/*
		for (const sequence of Object.values(sequences)) {
			sequence.start(0);
			console.log(sequence);
		}
		*/
	}

	if (Tone.Transport.state === 'started') {
		Tone.Transport.stop("+0.7");
		Tone.Destination.volume.rampTo(-Infinity, 0.5);
	}
	else {
		Tone.Transport.start("+0.2");
		Tone.Destination.volume.rampTo(config.vol, 0.1);
	}
}

async function touchEnded() {
	if (!initialised) {
		initialised = true;
		await Tone.start();
	}
	if (Tone.Transport.state === 'started') {
		Tone.Transport.stop('+0.7');
		Tone.Destination.volume.rampTo(-Infinity, 0.5);
	}
	else {
		Tone.Transport.start('+0.2');
		Tone.Destination.volume.rampTo(config.vol, 0.1);
	}
}

